import 'package:dartdap/dartdap.dart';

void main() async {
  var ldap = LdapConnection(hostname: 'ldap.example.com');
  await ldap.connect();
  var results = await ldap.search('dc=example,dc=com', Filter.eq('objectClass', 'person'));
  await for (var entry in results.entries) {
    print(entry.dn);
  }
  await ldap.close();
}
